<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import {ScanLine,BarChart3,Camera,CheckCircle,Plus,RefreshCw,Download,ArrowUpRight,Leaf,ShieldCheck,Activity} from 'lucide-vue-next'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,post,put,state,localDate,dateText,percent,download,type Dish} from '../api'
import Chart from '../components/Chart.vue'
import RoiSelector from '../components/RoiSelector.vue'
const props=defineProps<{page:string}>(),router=useRouter(),loading=ref(false),busy=ref(false),events=ref<any[]>([]),devices=ref<any[]>([]),dishes=ref<Dish[]>([]),entries=ref<any[]>([]),feedbacks=ref<any[]>([]),users=ref<any[]>([]),logs=ref<any[]>([]),legacy=ref<any[]>([]),stats=ref<any>({}),models=ref<any>({}),canteen=ref(''),filterStatus=ref('all'),from=ref(''),to=ref(''),menuDate=ref(localDate()),menuMeal=ref('午餐'),selectedDish=ref(''),dialog=ref(''),edit=ref<any>({}),job=ref<any>(null),file=ref<File>(),roi=ref([0,0,1,1]),snapshot=ref('')
let timer:ReturnType<typeof setInterval>|undefined,jobTimer:ReturnType<typeof setInterval>|undefined
const scopedCanteens=computed(()=>state.user?.role==='system_admin'?state.canteens:state.canteens.filter(c=>c.id===state.user?.canteen_id))
const windows=computed(()=>scopedCanteens.value.flatMap(c=>c.windows.map((w:any)=>({...w,label:c.name+' / '+w.name}))))
const eventPage=ref(1)
const filteredEvents=computed(()=>events.value.filter(r=>filterStatus.value==='all'||r.status===filterStatus.value))
const eventRows=computed(()=>props.page==='/'?filteredEvents.value.slice(0,8):filteredEvents.value.slice((eventPage.value-1)*15,eventPage.value*15))
watch(()=>[filterStatus.value,state.mode,props.page,canteen.value],()=>eventPage.value=1)
const trendOption=computed(()=>({color:['#2e8062'],tooltip:{trigger:'axis',valueFormatter:(v:number)=>v+'%'},grid:{left:45,right:20,top:30,bottom:30},xAxis:{type:'category',data:(stats.value.trend||[]).map((r:any)=>r.date.slice(5)),axisTick:{show:false},axisLine:{show:false}},yAxis:{type:'value',name:'面积占比 %',splitLine:{lineStyle:{color:'#edf0ea'}}},series:[{type:'line',smooth:true,symbolSize:7,data:(stats.value.trend||[]).map((r:any)=>(r.average_area_ratio*100).toFixed(1)),areaStyle:{color:'#e3efe7'},lineStyle:{width:3}}]}))
const gradeOption=computed(()=>({color:['#c7dfcd','#7dad8b','#e5c88f','#cf987e'],tooltip:{trigger:'item'},legend:{bottom:0,icon:'circle'},series:[{type:'pie',radius:['50%','72%'],center:['50%','43%'],label:{show:false},data:Object.entries(stats.value.grades||{}).map(([name,value])=>({name,value}))}]}))
async function load(silent=false){if(!silent)loading.value=true;try{
 if(['/','/monitor','/analytics'].includes(props.page)){const query=`mode=${state.mode}${canteen.value?'&canteen_id='+canteen.value:''}`;const result=await Promise.all([api('/waste-events?'+query),api('/analytics?'+query+(from.value?'&start='+from.value:'')+(to.value?'&end='+to.value:'')),api('/devices')]);events.value=result[0];stats.value=result[1];devices.value=result[2]}
 if(props.page==='/devices')devices.value=await api('/devices')
 if(['/dishes','/menus'].includes(props.page))dishes.value=await api('/dishes')
 if(props.page==='/menus')entries.value=await api('/menus/entries?date='+menuDate.value)
 if(props.page==='/feedback')feedbacks.value=await api('/feedback')
 if(props.page==='/users')users.value=await api('/admin/users')
 if(props.page==='/models')models.value=await api('/admin/model-config')
 if(props.page==='/logs'){logs.value=await api('/admin/audit-logs');legacy.value=await api('/admin/legacy-records')}
 if(props.page==='/canteens')state.canteens=await api('/canteens')
 }catch{}finally{loading.value=false}}
watch(()=>[props.page,state.mode,canteen.value,from.value,to.value,menuDate.value],()=>{load();if(timer)clearInterval(timer);if(['/','/monitor','/devices'].includes(props.page))timer=setInterval(()=>load(true),5000)},{immediate:true})
function editDish(d?:Dish){edit.value=d?{...d,ingredientsText:d.ingredients.join('、'),allergensText:(d.allergens||[]).join('、'),allergensKnown:d.allergens!==null}:{name:'',window_id:windows.value[0]?.id,category:'蔬菜',price:4,portion_g:150,kcal:100,protein:3,fat:4,carbs:12,ingredientsText:'',allergensText:'',allergensKnown:true,nutrition_source:'食堂配方估算',image_url:'/assets/vegetables.svg',active:true,is_demo:state.mode==='demo'};dialog.value='dish'}
const split=(text:string)=>text.split(/[,，、\n]/).map(s=>s.trim()).filter(Boolean)
async function saveDish(){busy.value=true;try{const data={...edit.value,ingredients:split(edit.value.ingredientsText),allergens:edit.value.allergensKnown?split(edit.value.allergensText):null};if(edit.value.id)await put('/dishes/'+edit.value.id,data);else await post('/dishes',data);dialog.value='';await load();ElMessage.success('菜品已保存')}catch{}finally{busy.value=false}}
async function publish(dishId=selectedDish.value,available=true,meal=menuMeal.value){try{await post('/menus',{date:menuDate.value,meal,dish_id:dishId,available});await load();ElMessage.success(available?'菜单已发布':'已暂停供应')}catch{}}
function editDevice(d?:any){edit.value=d?{...d}:{name:'',canteen_id:scopedCanteens.value[0]?.id,source_type:'demo',source:'',roi:[0,0,1,1]};dialog.value='device'}
async function saveDevice(){busy.value=true;try{if(edit.value.id)await put('/devices/'+edit.value.id,edit.value);else await post('/devices',edit.value);dialog.value='';await load();ElMessage.success('设备配置已保存')}catch{}finally{busy.value=false}}
async function toggle(d:any){try{await post('/devices/'+d.id+'/toggle');await load()}catch{}}
function deviceStatus(d:any){if(!d.enabled)return '已停止';if(!d.heartbeat||Date.now()-new Date(d.heartbeat).getTime()>20000)return '等待采集服务';return {online:'在线',error:'异常，正在重连',starting:'启动中',stopped:'已停止'}[d.status as string]||d.status}
async function detect(){busy.value=true;try{const form=new FormData();const cid=canteen.value||scopedCanteens.value[0]?.id;if(!cid){ElMessage.warning('请先创建食堂');return};form.append('canteen_id',cid);form.append('mode',state.mode);if(file.value)form.append('image',file.value);form.append('roi',JSON.stringify(roi.value));job.value=await api('/detection-jobs',{method:'POST',body:form});if(jobTimer)clearInterval(jobTimer);jobTimer=setInterval(async()=>{try{job.value=await api('/detection-jobs/'+job.value.id);if(['done','failed'].includes(job.value.status)){clearInterval(jobTimer);await load();ElMessage.success('检测任务已处理')}}catch{clearInterval(jobTimer)}},1200)}catch{}finally{busy.value=false}}
async function reviewEvent(row:any){edit.value={...row,area_percent:row.area_ratio==null?null:row.area_ratio*100,note:'',status:'verified'};if(snapshot.value)URL.revokeObjectURL(snapshot.value);snapshot.value='';dialog.value='review';if(row.snapshot){try{let response=await fetch(row.snapshot,{headers:{Authorization:'Bearer '+state.token}});if(response.ok)snapshot.value=URL.createObjectURL(await response.blob())}catch{}}}
async function saveReview(){try{await post('/waste-events/'+edit.value.id+'/review',{area_ratio:edit.value.area_percent==null?null:edit.value.area_percent/100,status:edit.value.status,note:edit.value.note});dialog.value='';await load();ElMessage.success('核验结果已保存')}catch{}}
async function saveModels(){try{await put('/admin/model-config',models.value);ElMessage.success('模型配置已更新');await load()}catch{}}
function editUser(row:any){edit.value={...row};dialog.value='user'}
async function saveUser(){try{await put('/admin/users/'+edit.value.id,edit.value);dialog.value='';await load();ElMessage.success('用户权限已更新，原会话已撤销')}catch{}}
async function resetPassword(row:any){try{const result=await ElMessageBox.prompt('输入新密码（至少8位）','重置 '+row.username+' 的密码',{inputType:'password',inputValidator:(v:string)=>v.length>=8||'至少8位'});await post('/admin/users/'+row.id+'/reset-password',{password:result.value});ElMessage.success('密码已重置')}catch{}}
async function reply(row:any){try{const result=await ElMessageBox.prompt('请输入回复（最多80字）','回复反馈',{inputValidator:(v:string)=>!!v&&v.length<=80||'请填写1–80字'});await post('/feedback/'+row.id+'/reply',{name:result.value});await load()}catch{}}
async function addPlace(){try{await post('/admin/'+(dialog.value==='canteen'?'canteens':'windows'),edit.value);dialog.value='';await load();ElMessage.success('已添加')}catch{}}
function openDisplay(){const id=canteen.value||scopedCanteens.value[0]?.id;if(id)window.open('#/display/'+id+'?mode='+state.mode,'_blank','noopener')}
onBeforeUnmount(()=>{clearInterval(timer);clearInterval(jobTimer);if(snapshot.value)URL.revokeObjectURL(snapshot.value)})
</script>
<template><div v-loading="loading">
<template v-if="['/','/monitor','/analytics'].includes(page)"><div class="section-heading"><div><h2>{{page==='/'?'让数据帮助食堂，更进一步':page==='/monitor'?'看见剩余，也看见改变':'少一点剩余，多一份珍惜'}}</h2><p class="muted">匿名统计 · 面积占比不代表重量浪费率 · 待核验记录不计入均值</p></div><el-button @click="load()"><RefreshCw :size="15"/>刷新</el-button></div><div class="toolbar"><el-select v-if="state.user?.role==='system_admin'" v-model="canteen" clearable placeholder="全部食堂" style="width:170px"><el-option v-for="c in scopedCanteens" :key="c.id" :value="c.id" :label="c.name"/></el-select><template v-if="page==='/analytics'"><el-date-picker v-model="from" value-format="YYYY-MM-DD" placeholder="开始日期"/><el-date-picker v-model="to" value-format="YYYY-MM-DD" placeholder="结束日期"/></template><el-button @click="download('/analytics/export?mode='+state.mode+(canteen?'&canteen_id='+canteen:'')+(from?'&start='+from:'')+(to?'&end='+to:''),'waste-events.csv')"><Download :size="16"/>导出筛选记录</el-button><el-button @click="openDisplay">回收处大屏 <ArrowUpRight :size="15"/></el-button></div><div class="metrics"><div class="metric"><span class="metric-icon"><ScanLine/></span><div><label>餐盘记录数</label><strong>{{stats.total||0}} <small>次</small></strong><span>当前筛选范围</span></div></div><div class="metric"><span class="metric-icon amber"><BarChart3/></span><div><label>平均剩余面积占比</label><strong>{{stats.average_area_ratio==null?'—':(stats.average_area_ratio*100).toFixed(1)}}<small v-if="stats.average_area_ratio!=null">%</small></strong><span>仅统计已核验记录</span></div></div><div class="metric"><span class="metric-icon blue"><ShieldCheck/></span><div><label>待人工核验</label><strong>{{stats.pending||0}} <small>条</small></strong><span>低置信度或模型未就绪</span></div></div><div class="metric"><span class="metric-icon pink"><Camera/></span><div><label>采集设备</label><strong>{{devices.filter(d=>deviceStatus(d)==='在线').length}} <small>/ {{devices.length}}</small></strong><span>在线设备 / 总设备</span></div></div></div>
<div v-if="page!=='/monitor'" class="two-col charts-row"><section class="panel"><div class="section-heading"><h3>剩余面积变化趋势</h3><span class="tiny-badge">{{state.mode==='demo'?'演示':'真实'}}</span></div><Chart :option="trendOption"/></section><section class="panel"><h3>剩余等级分布</h3><Chart :option="gradeOption"/></section></div>
<div v-if="page==='/monitor'" class="two-col monitor-row"><section class="panel"><div class="section-heading"><h3>餐盘检测工作台</h3><span class="tiny-badge">{{state.mode==='demo'?'模拟检测':'真实检测'}}</span></div><div v-if="state.mode==='demo'" class="demo-preview"><img src="/assets/tray.svg" alt="模拟餐盘"><b>演示餐盘检测</b><p class="muted small">点击生成模拟事件，体验任务、核验与看板流程。<br>演示结果不来自YOLO推理。</p></div><RoiSelector v-else @selected="(f:File,r:number[])=>{file=f;roi=r}"/><el-button class="full" type="primary" :loading="busy" @click="detect"><ScanLine :size="17"/>{{state.mode==='demo'?'生成模拟检测':'提交YOLO检测任务'}}</el-button><div v-if="job" class="job-status"><b>任务：{{{queued:'排队中',processing:'检测中',done:'已完成',failed:'失败'}[job.status as string]}}</b><p class="small muted">{{job.error||'任务由独立采集进程处理；排队过久请检查worker是否启动。'}}</p></div></section><section class="panel"><div class="section-heading"><h3>回收设备状态</h3><router-link class="text-link" to="/devices">管理设备 <ArrowUpRight :size="14"/></router-link></div><div v-for="d in devices" :key="d.id" class="device-item"><Camera :size="22"/><div><b>{{d.name}}</b><small>{{deviceStatus(d)}}</small><small v-if="d.error" class="error-text">{{d.error}}</small></div><el-tag :type="d.status==='online'?'success':'info'">{{d.source_type}}</el-tag></div><el-alert title="固定机位采集启动时请保持餐盘区域为空，用于背景标定；餐盘放稳后检测，离开后再接收下一次。" type="info" :closable="false"/><div class="monitor-note"><Leaf/><h3>每一次反馈，都让取餐更合适</h3><p>匿名回收数据用于食堂改善，个人营养建议来自学生主动填写的档案与记录。</p></div></section></div>
<section class="panel"><div class="section-heading"><h3>{{page==='/monitor'?'检测记录与核验':'最近监测记录'}}</h3><el-segmented v-model="filterStatus" :options="[{label:'全部',value:'all'},{label:'待核验',value:'pending'},{label:'已核验',value:'verified'},{label:'已排除',value:'rejected'}]"/></div><el-table :data="eventRows" empty-text="当前模式暂无餐盘记录"><el-table-column label="检测时间" min-width="175"><template #default="{row}">{{dateText(row.created_at)}}</template></el-table-column><el-table-column prop="source" label="来源" width="90"/><el-table-column label="剩余面积占比" min-width="120"><template #default="{row}">{{percent(row.area_ratio)}}</template></el-table-column><el-table-column prop="grade" label="等级" width="110"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.status==='verified'?'success':row.status==='pending'?'warning':'info'">{{{verified:'已核验',pending:'待核验',rejected:'已排除'}[row.status as string]}}</el-tag></template></el-table-column><el-table-column prop="model_version" label="模型" min-width="160"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="reviewEvent(row)">查看核验</el-button></template></el-table-column></el-table><el-pagination v-if="page!=='/'&&filteredEvents.length>15" v-model:current-page="eventPage" :page-size="15" :total="filteredEvents.length" layout="prev,pager,next,total" class="table-pagination"/></section></template>
<template v-else-if="page==='/dishes'"><div class="section-heading"><div><h2>维护真实、清晰的菜品信息</h2><p class="muted">营养数据按每份录入，过敏原未知时请明确标记。</p></div><el-button type="primary" @click="editDish()"><Plus :size="16"/>新增菜品</el-button></div><section class="panel"><el-table :data="dishes.filter(d=>d.is_demo===(state.mode==='demo'))"><el-table-column label="菜品" min-width="190"><template #default="{row}"><div class="table-dish"><img :src="row.image_url||'/assets/vegetables.svg'" :alt="row.name"><b>{{row.name}}</b></div></template></el-table-column><el-table-column prop="canteen_name" label="食堂"/><el-table-column prop="category" label="分类"/><el-table-column label="价格"><template #default="{row}">¥{{row.price}}</template></el-table-column><el-table-column label="营养 / 每份"><template #default="{row}">{{row.kcal}} kcal<br>{{row.protein}}g 蛋白质</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?'已上架':'已下架'}}</el-tag></template></el-table-column><el-table-column width="100"><template #default="{row}"><el-button link type="primary" @click="editDish(row)">编辑</el-button></template></el-table-column></el-table></section></template>
<template v-else-if="page==='/menus'"><section class="panel"><h2>每日菜单发布</h2><p class="muted">只有当天发布且正在供应的菜品，才会进入学生推荐。</p><div class="toolbar"><el-date-picker v-model="menuDate" value-format="YYYY-MM-DD" :clearable="false"/><el-select v-model="menuMeal" style="width:100px"><el-option v-for="m in ['早餐','午餐','晚餐']" :key="m" :value="m"/></el-select><el-select v-model="selectedDish" placeholder="选择菜品" filterable style="width:240px"><el-option v-for="d in dishes.filter(d=>d.active&&d.is_demo===(state.mode==='demo'))" :key="d.id" :label="d.name+' / '+d.canteen_name" :value="d.id"/></el-select><el-button type="primary" @click="publish()">发布到菜单</el-button></div><el-table :data="entries.filter(e=>dishes.find(d=>d.id===e.dish_id)?.is_demo===(state.mode==='demo'))"><el-table-column prop="date" label="供应日期"/><el-table-column prop="meal" label="餐次"/><el-table-column prop="dish_name" label="菜品"/><el-table-column label="供应状态"><template #default="{row}"><el-tag :type="row.available?'success':'info'">{{row.available?'供应中':'已售罄 / 暂停'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="publish(row.dish_id,!row.available,row.meal)">{{row.available?'暂停供应':'恢复供应'}}</el-button></template></el-table-column></el-table></section></template>
<template v-else-if="page==='/devices'"><div class="section-heading"><div><h2>让每个回收点，保持连接</h2><p class="muted">采集由独立worker运行；配置变更前先停止设备。</p></div><el-button v-if="state.user?.role==='system_admin'" type="primary" @click="editDevice()"><Plus :size="16"/>添加设备</el-button></div><div class="device-grid"><section class="panel" v-for="d in devices" :key="d.id"><div class="section-heading"><Camera :size="28"/><el-tag :type="deviceStatus(d)==='在线'?'success':'info'">{{deviceStatus(d)}}</el-tag></div><h3>{{d.name}}</h3><p class="muted small">{{d.source_type.toUpperCase()}} · {{state.canteens.find(c=>c.id===d.canteen_id)?.name}}</p><p class="small">ROI：{{d.roi.join(' / ')}}</p><p class="small muted">最近心跳：{{d.heartbeat?dateText(d.heartbeat):'暂无'}}</p><p v-if="d.error" class="error-text small">{{d.error}}</p><div class="row"><el-button :type="d.enabled?'danger':'primary'" @click="toggle(d)">{{d.enabled?'停止设备':'启动设备'}}</el-button><el-button v-if="state.user?.role==='system_admin'" :disabled="d.enabled" @click="editDevice(d)">编辑配置</el-button></div></section></div><el-empty v-if="!devices.length" description="尚未配置设备"/></template>
<template v-else-if="page==='/feedback'"><section class="panel"><h2>听见学生的每一条建议</h2><el-empty v-if="!feedbacks.length" description="暂无反馈"/><article v-for="f in feedbacks" :key="f.id" class="feedback-item"><div class="section-heading"><el-rate :model-value="f.rating" disabled/><span class="muted small">{{dateText(f.created_at)}}</span></div><p>{{f.content}}</p><blockquote v-if="f.reply">食堂回复：{{f.reply}}</blockquote><el-button link type="primary" @click="reply(f)">{{f.reply?'更新回复':'回复反馈'}}</el-button></article></section></template>
<template v-else-if="page==='/users'"><section class="panel"><h2>用户与权限</h2><p class="muted">学生只能通过注册获得学生角色；管理员在此分配权限。</p><el-table :data="users"><el-table-column prop="username" label="账号"/><el-table-column label="角色"><template #default="{row}">{{{student:'学生',canteen_admin:'食堂管理员',system_admin:'系统管理员'}[row.role as string]}}</template></el-table-column><el-table-column label="授权食堂"><template #default="{row}">{{state.canteens.find(c=>c.id===row.canteen_id)?.name||'—'}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{row.active?'正常':'已禁用'}}</template></el-table-column><el-table-column label="操作" width="200"><template #default="{row}"><el-button link type="primary" @click="editUser(row)">编辑权限</el-button><el-button link type="danger" @click="resetPassword(row)">重置密码</el-button></template></el-table-column></el-table></section></template>
<template v-else-if="page==='/canteens'"><div class="section-heading"><h2>食堂与窗口</h2><el-button type="primary" @click="dialog='canteen';edit={name:''}">新增食堂</el-button></div><div class="device-grid"><section v-for="c in state.canteens" :key="c.id" class="panel"><h3>{{c.name}}</h3><div class="window-item" v-for="w in c.windows" :key="w.id">{{w.name}}</div><el-button text type="primary" @click="dialog='window';edit={name:'',canteen_id:c.id}">+ 添加窗口</el-button></section></div></template>
<template v-else-if="page==='/models'"><section class="panel narrow"><h2>模型与分级配置</h2><p class="muted">密钥仅保存在后端，读取接口不回传明文。桌面演示请使用专用测试密钥。</p><el-form label-position="top" @submit.prevent="saveModels"><el-form-item label="兼容接口 Base URL（含 /v1，不含 /chat/completions）"><el-input v-model="models.llm_base_url" placeholder="https://provider.example/v1"/></el-form-item><el-form-item label="模型名称"><el-input v-model="models.llm_model"/></el-form-item><el-form-item :label="'API密钥 · '+(models.api_key_configured?'已配置，留空保留':'尚未配置')"><el-input v-model="models.llm_api_key" type="password" show-password placeholder="留空不修改；清除请使用下方按钮"/></el-form-item><el-button text type="danger" @click="models.llm_api_key='';saveModels()">清除密钥</el-button><el-form-item label="接口超时 / 秒"><el-input-number v-model="models.llm_timeout" :min="1" :max="60"/></el-form-item><el-form-item label="本地YOLO分割权重路径"><el-input v-model="models.yolo_weights" placeholder="D:/models/best.pt"/></el-form-item><el-form-item label="剩余等级阈值（0~1，小于1%为默认无明显剩余）"><div class="toolbar"><el-input-number v-for="(_,i) in models.thresholds" :key="i" v-model="models.thresholds[i]" :min="0.001" :max="0.999" :step="0.01" :precision="3"/></div></el-form-item><el-button type="primary" native-type="submit">保存模型配置</el-button></el-form></section></template>
<template v-else-if="page==='/logs'"><section class="panel"><h2>系统操作日志</h2><el-table :data="logs"><el-table-column label="时间" min-width="175"><template #default="{row}">{{dateText(row.created_at)}}</template></el-table-column><el-table-column prop="action" label="操作"/><el-table-column prop="user_id" label="操作人ID"/><el-table-column prop="target" label="目标"/><el-table-column label="摘要"><template #default="{row}">{{JSON.stringify(row.detail)}}</template></el-table-column></el-table><h3>历史重量记录（独立口径）</h3><p class="muted">已导入 {{legacy.length}} 条，未混入面积占比看板。</p><el-table v-if="legacy.length" :data="legacy"><el-table-column prop="id" label="历史ID"/><el-table-column label="原始数据"><template #default="{row}">{{JSON.stringify(row.data)}}</template></el-table-column></el-table></section></template>
<el-empty v-else description="页面不存在或当前角色无此功能"/>
<el-dialog :model-value="!!dialog" @close="dialog=''" :title="{dish:'维护菜品信息',device:'设备配置',review:'餐盘核验',user:'用户权限',canteen:'新增食堂',window:'新增窗口'}[dialog]" width="min(720px,94vw)">
<el-form v-if="dialog==='dish'" label-position="top"><div class="form-grid"><el-form-item label="菜品名称"><el-input v-model="edit.name"/></el-form-item><el-form-item label="所属窗口"><el-select v-model="edit.window_id"><el-option v-for="w in windows" :key="w.id" :label="w.label" :value="w.id"/></el-select></el-form-item><el-form-item label="分类"><el-select v-model="edit.category"><el-option v-for="c in ['主食','蛋白类','蔬菜','水果']" :key="c" :value="c"/></el-select></el-form-item><el-form-item label="价格 / 元"><el-input-number v-model="edit.price" :min="0" :max="500"/></el-form-item><el-form-item v-for="(label,key) in {portion_g:'份量 / g',kcal:'每份能量 / kcal',protein:'蛋白质 / g',fat:'脂肪 / g',carbs:'碳水 / g'}" :key="key" :label="label"><el-input-number v-model="edit[key]" :min="0"/></el-form-item></div><el-form-item label="食材（顿号分隔）"><el-input v-model="edit.ingredientsText"/></el-form-item><el-checkbox v-model="edit.allergensKnown">过敏原信息已核对</el-checkbox><el-form-item label="过敏原（已核对且无过敏原可留空）"><el-input v-model="edit.allergensText" :disabled="!edit.allergensKnown"/></el-form-item><el-form-item label="营养来源"><el-input v-model="edit.nutrition_source"/></el-form-item><el-form-item label="菜品插画"><el-select v-model="edit.image_url"><el-option v-for="(label,key) in {rice:'米饭',chicken:'鸡肉',egg:'鸡蛋',tofu:'豆腐',vegetables:'蔬菜',fruit:'水果'}" :key="key" :label="label" :value="'/assets/'+key+'.svg'"/></el-select></el-form-item><el-checkbox v-model="edit.active">上架菜品</el-checkbox><el-checkbox v-model="edit.is_demo">演示菜品</el-checkbox></el-form>
<el-form v-else-if="dialog==='device'" label-position="top"><el-form-item label="设备名称"><el-input v-model="edit.name"/></el-form-item><el-form-item label="所属食堂"><el-select v-model="edit.canteen_id"><el-option v-for="c in scopedCanteens" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="视频源类型"><el-select v-model="edit.source_type"><el-option v-for="(label,key) in {demo:'模拟设备',usb:'USB摄像头',rtsp:'RTSP网络摄像头',video:'本地视频回放'}" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="来源地址 / 索引"><el-input v-model="edit.source" placeholder="USB填0；RTSP填地址；视频填后端文件绝对路径"/></el-form-item><el-form-item label="餐盘有效区域 [x, y, width, height]，归一化0~1"><div class="form-grid"><el-input-number v-for="(_,i) in edit.roi" :key="i" v-model="edit.roi[i]" :min="0" :max="1" :step="0.05" :precision="2"/></div></el-form-item><el-alert title="设备启动时区域内须为空，保持机位固定；当前背景差分方案适合单餐盘依次回收的毕设演示。" type="info" :closable="false"/></el-form>
<el-form v-else-if="dialog==='review'" label-position="top"><img v-if="snapshot" class="review-snapshot" :src="snapshot" alt="仅包含餐盘区域的截图"><el-alert v-else title="截图不存在或已过期，可根据记录摘要核验。" type="info" :closable="false"/><p class="small muted">原始检测：{{JSON.stringify(edit.detections)}}</p><el-form-item label="人工估计剩余面积占比 / %"><el-input-number v-model="edit.area_percent" :min="0" :max="100" :precision="1"/></el-form-item><el-form-item label="核验结果"><el-radio-group v-model="edit.status"><el-radio value="verified">确认记录</el-radio><el-radio value="rejected">排除误检</el-radio></el-radio-group></el-form-item><el-form-item label="核验说明（必填）"><el-input v-model="edit.note" type="textarea" maxlength="500"/></el-form-item><details><summary>历史核验记录</summary><pre>{{JSON.stringify(edit.review_history,null,2)}}</pre></details></el-form>
<el-form v-else-if="dialog==='user'" label-position="top"><el-form-item label="角色"><el-select v-model="edit.role"><el-option v-for="(label,key) in {student:'学生',canteen_admin:'食堂管理员',system_admin:'系统管理员'}" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item v-if="edit.role==='canteen_admin'" label="授权食堂"><el-select v-model="edit.canteen_id"><el-option v-for="c in state.canteens" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-checkbox v-model="edit.active">启用账号</el-checkbox></el-form>
<el-form v-else label-position="top"><el-form-item label="名称"><el-input v-model="edit.name"/></el-form-item></el-form>
<template #footer><el-button @click="dialog=''">取消</el-button><el-button type="primary" :loading="busy" @click="dialog==='dish'?saveDish():dialog==='device'?saveDevice():dialog==='review'?saveReview():dialog==='user'?saveUser():addPlace()">保存</el-button></template></el-dialog>
</div></template>
